#include <functional>
#include <iostream>

int main() {
    std::function<int(int)> ampliar = [](int n) { return n + 5; };
    std::cout << ampliar(10) << '\n';
    ampliar = [](int n) { return n * 2; };
    std::cout << ampliar(10) << '\n';
}
